function (settings, time, ctx) {
  // ---------- SETTINGS ----------
  var LABEL        = settings.label.value;          // caption right of the dial ('' = none)
  var UNIT         = settings.unit.value;           // unit under the caption, Airbus cyan ('' = none)
  var VALUE_MODE   = settings.value_mode.value;     // 'percent' (value / Max * 100, Airbus N1 look) | 'value' (column value * multiplier)
  var MULTIPLIER   = settings.multiplier.value;     // value * multiplier before anything else (1 = escRPM as is; gear ratio, pole correction)
  var DIGITS       = settings.digits.value;         // decimal places of the value in the box
  var SMOOTH_MS    = settings.smooth_ms.value;      // smoothing window in ms, centered on the current time (0 = off)
  var MAX          = settings.max.value;            // end of the dial in column units (after the multiplier); = 100 % in percent mode
  var RED_FROM     = settings.red_from.value;       // start of the red band in column units (0 = no red band)
  var NUM_STEP     = settings.number_step.value;    // column units between two dial numbers (long ticks)
  var NUM_DIVISOR  = settings.number_divisor.value; // dial numbers = value / divisor (Airbus: 5, 10 for 5000, 10000)
  var MINOR        = settings.minor_ticks.value;    // short ticks between two numbers (0 = none)
  var START_ANGLE  = settings.start_angle.value;    // dial angle of value 0 in degrees (0 = 12 o'clock, clockwise; Airbus -120)
  var END_ANGLE    = settings.end_angle.value;      // dial angle of Max in degrees (Airbus 95)
  var KNEE         = settings.knee_value.value;     // the scale is compressed below this value like on the ECAM (0 = linear scale)
  var KNEE_ANGLE   = settings.knee_angle.value;     // dial angle of the knee value in degrees
  var IDLE_TEXT    = settings.idle_text.value;      // text shown above the caption while the value is below Idle below ('' = none)
  var IDLE_BELOW   = settings.idle_below.value;     // show the idle text below this value, column units (0 = never)
  var NEEDLE_LEN   = settings.needle_length.value;  // needle length in % of the dial radius (125 = reaches past the arc like the ECAM)
  var TIP_CIRCLE   = settings.tip_circle.value;     // small hollow circle at the needle tip
  var NEEDLE_COLOR = settings.needle_color.value;   // needle color
  var TIP_COLOR    = settings.tip_color.value;      // tip circle color
  var TRACK_COLOR  = settings.track_color.value;    // dial arc, ticks
  var RED_COLOR    = settings.red_color.value;      // red band color
  var BOX_COLOR    = settings.box_color.value;      // value box background
  var BOX_BORDER   = settings.box_border.value;     // value box border color
  var VALUE_COLOR  = settings.value_color.value;    // value color
  var NUM_COLOR    = settings.number_color.value;   // dial numbers
  var LABEL_COLOR  = settings.label_color.value;    // caption color
  var UNIT_COLOR   = settings.unit_color.value;     // unit color (Airbus cyan)
  var IDLE_COLOR   = settings.idle_color.value;     // idle text color
  var BG           = settings.background.value;     // whole box background; alpha 0 = none
  var RADIUS       = settings.radius.value;         // box corner radius at the default 300x150 size; scales with the widget
  var OPACITY      = settings.opacity.value;        // whole-widget opacity 0..1 (1 = opaque)
  var FONT         = settings.font.value;           // font family
  var VALUE_SIZE   = settings.value_size.value;     // value font size at the default 300x150 size; scales with the widget
  var NUM_SIZE     = settings.number_size.value;    // dial numbers font size at the default size; scales with the widget
  var LABEL_SIZE   = settings.label_size.value;     // caption font size at the default size; scales with the widget
  var UNIT_SIZE    = settings.unit_size.value;      // unit font size at the default size; scales with the widget
  var IDLE_SIZE    = settings.idle_size.value;      // idle text font size at the default size; scales with the widget
  var LINE_WIDTH   = settings.line_width.value;     // arc / tick / needle stroke at the default size; scales with the widget
  var SHADOW       = settings.text_shadow.value;    // CSS text shadow for all texts ('' = none)
  // -------------------------------
  var W = ctx.width, H = ctx.height, s = ctx.state, i;
  var scale = Math.min(W / 300, H / 150);
  var col = ctx.columns[0];
  if (!(MAX > 0)) MAX = 1;

  // ---- value (smoothed when asked; only inside the telemetry range) ----
  var raw = ctx.values[0], cur;
  if (typeof raw === 'number') {
    if (SMOOTH_MS > 0 && col) {
      var sam = ctx.range(col, time - SMOOTH_MS / 2, time + SMOOTH_MS / 2, 400) || [], sum = 0, cnt = 0;
      for (i = 0; i < sam.length; i++) if (typeof sam[i].v === 'number') { sum += sam[i].v; cnt++; }
      cur = cnt ? sum / cnt : raw;
    } else cur = raw;
    cur *= MULTIPLIER;
  }

  // ---- geometry (everything from the dial radius) ----
  var fs = VALUE_SIZE * scale, nfs = NUM_SIZE * scale, lfs = LABEL_SIZE * scale, ufs = UNIT_SIZE * scale, ifs = IDLE_SIZE * scale;
  var sw = LINE_WIDTH * scale, pad = 6 * scale;
  var R = 80 * scale, nl = Math.max(0.3, NEEDLE_LEN / 100), tipR = 4 * scale;
  var reach = R * Math.max(nl, 1) + (TIP_CIRCLE ? tipR + sw : sw) + 1.5 * scale;   // farthest thing from the centre
  var cx = reach + 2 * scale, cy = reach + 2 * scale;
  var a0 = START_ANGLE, a1 = END_ANGLE;
  if (a1 <= a0) a1 = a0 + 1;
  function ang(v) {                                    // value -> dial angle, with the ECAM knee
    v = Math.max(0, Math.min(MAX, v));
    if (KNEE > 0 && KNEE < MAX && KNEE_ANGLE > a0 && KNEE_ANGLE < a1)
      return v <= KNEE ? a0 + (KNEE_ANGLE - a0) * v / KNEE : KNEE_ANGLE + (a1 - KNEE_ANGLE) * (v - KNEE) / (MAX - KNEE);
    return a0 + (a1 - a0) * v / MAX;
  }
  function pt(r, a) { var t = a * Math.PI / 180; return [(cx + r * Math.sin(t)).toFixed(2), (cy - r * Math.cos(t)).toFixed(2)]; }
  function arc(r, b1, b2, color, width, extra) {
    if (b2 - b1 < 0.05) return '';
    var p1 = pt(r, b1), p2 = pt(r, b2);
    return '<path d="M' + p1[0] + ',' + p1[1] + ' A' + r.toFixed(2) + ',' + r.toFixed(2) + ' 0 ' + ((b2 - b1) > 180 ? 1 : 0) + ' 1 ' + p2[0] + ',' + p2[1]
      + '" fill="none" stroke="' + color + '" stroke-width="' + width.toFixed(2) + '" stroke-linecap="butt"' + (extra || '') + '/>';
  }
  function fmtVal(v) { return VALUE_MODE === 'percent' ? (v / MAX * 100).toFixed(DIGITS) : v.toFixed(DIGITS); }
  var shadow = SHADOW ? ' style="text-shadow:' + SHADOW + '"' : '';

  // value box: fixed width from the longest value it can show (no breathing while the value changes)
  var bw = Math.max(R, fmtVal(MAX).length * fs * 0.6 + 12 * scale), bh = fs * 1.35, bx = cx - bw / 2, by = cy + 2 * scale;
  var dialRight = cx + reach, lx = (dialRight + W) / 2;   // caption column right of the dial

  // ---- static part: panel, arc, red band, ticks, numbers, caption, unit ----
  var staticKey = W + 'x' + H + '|' + MAX + '|' + RED_FROM + '|' + NUM_STEP + '|' + NUM_DIVISOR + '|' + MINOR + '|' + a0 + '|' + a1 + '|' + KNEE + '|' + KNEE_ANGLE
    + '|' + NEEDLE_LEN + '|' + TIP_CIRCLE + '|' + TRACK_COLOR + '|' + RED_COLOR + '|' + NUM_COLOR + '|' + LABEL + '|' + LABEL_COLOR + '|' + UNIT + '|' + UNIT_COLOR
    + '|' + BG + '|' + RADIUS + '|' + nfs + '|' + lfs + '|' + ufs + '|' + sw + '|' + SHADOW;
  if (s.staticKey !== staticKey) {
    var sv = '';
    if (BG && BG !== 'rgba(0,0,0,0)') sv += '<rect x="0" y="0" width="' + W + '" height="' + H + '" rx="' + (RADIUS * scale).toFixed(1) + '" fill="' + BG + '"/>';
    sv += arc(R, a0, a1, TRACK_COLOR, sw);
    if (RED_FROM > 0 && RED_FROM < MAX) {
      var rw = 8 * scale;                              // red band sits on the arc, bulging outwards
      sv += arc(R + rw / 2 - sw / 2, ang(RED_FROM), a1, RED_COLOR, rw);
    }
    var minor = Math.max(0, Math.round(MINOR)) + 1, tick = NUM_STEP > 0 ? NUM_STEP / minor : 0;
    if (tick > 0) {
      var n = Math.floor(MAX / tick + 1e-9);
      if (n > 200) { tick = MAX / 200; n = 200; }       // guard against a silly step
      for (i = 0; i <= n; i++) {
        var v = i * tick, a = ang(v), major = (i % minor === 0), len = major ? R * 0.14 : R * 0.08;
        var q1 = pt(R, a), q2 = pt(R - len, a);
        sv += '<line x1="' + q1[0] + '" y1="' + q1[1] + '" x2="' + q2[0] + '" y2="' + q2[1] + '" stroke="' + TRACK_COLOR + '" stroke-width="' + (major ? sw : sw * 0.75).toFixed(2) + '"/>';
        if (major && i > 0) {
          var nv = Math.round(v / NUM_STEP) * NUM_STEP / (NUM_DIVISOR || 1), np = pt(R * 0.64, a);
          sv += '<text x="' + np[0] + '" y="' + np[1] + '" fill="' + NUM_COLOR + '" font-size="' + nfs.toFixed(1) + '" text-anchor="middle" dominant-baseline="central"' + shadow + '>' + (Math.round(nv * 100) / 100) + '</text>';
        }
      }
    }
    if (LABEL) sv += '<text x="' + lx.toFixed(2) + '" y="' + (cy - (UNIT ? ufs * 0.15 : 0)).toFixed(2) + '" fill="' + LABEL_COLOR + '" font-size="' + lfs.toFixed(1) + '" text-anchor="middle" dominant-baseline="auto"' + shadow + '>' + LABEL + '</text>';
    if (UNIT) sv += '<text x="' + lx.toFixed(2) + '" y="' + (cy + (LABEL ? ufs * 0.95 : ufs * 0.35)).toFixed(2) + '" fill="' + UNIT_COLOR + '" font-size="' + ufs.toFixed(1) + '" text-anchor="middle" dominant-baseline="auto"' + shadow + '>' + UNIT + '</text>';
    s.staticSvg = sv; s.staticKey = staticKey;
  }

  var out = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" style="display:block;font-family:' + FONT + ';opacity:' + OPACITY + '">' + s.staticSvg;

  // ---- needle (under the value box, like on the ECAM) ----
  if (typeof cur === 'number') {
    var na = ang(cur), t = na * Math.PI / 180, ux = Math.sin(t), uy = -Math.cos(t), px = -uy, py = ux;
    var L = R * nl, hb = Math.max(sw * 0.9, 2 * scale), ht = Math.max(sw * 0.35, 0.8 * scale);
    var d = 'M' + (cx + px * hb).toFixed(2) + ',' + (cy + py * hb).toFixed(2) + ' L' + (cx + ux * L + px * ht).toFixed(2) + ',' + (cy + uy * L + py * ht).toFixed(2)
      + ' L' + (cx + ux * L - px * ht).toFixed(2) + ',' + (cy + uy * L - py * ht).toFixed(2) + ' L' + (cx - px * hb).toFixed(2) + ',' + (cy - py * hb).toFixed(2) + ' Z';
    out += '<path d="' + d + '" fill="' + NEEDLE_COLOR + '" stroke="' + NEEDLE_COLOR + '" stroke-width="' + (0.6 * scale).toFixed(2) + '" stroke-linejoin="round"/>';
    if (TIP_CIRCLE) out += '<circle cx="' + (cx + ux * L).toFixed(2) + '" cy="' + (cy + uy * L).toFixed(2) + '" r="' + tipR.toFixed(2) + '" fill="none" stroke="' + TIP_COLOR + '" stroke-width="' + (sw * 0.75).toFixed(2) + '"/>';
  }

  // ---- value box ----
  out += '<rect x="' + bx.toFixed(2) + '" y="' + by.toFixed(2) + '" width="' + bw.toFixed(2) + '" height="' + bh.toFixed(2) + '" fill="' + BOX_COLOR + '" stroke="' + BOX_BORDER + '" stroke-width="' + sw.toFixed(2) + '"/>'
    + '<text x="' + cx.toFixed(2) + '" y="' + (by + bh / 2 + fs * 0.36).toFixed(2) + '" fill="' + VALUE_COLOR + '" font-size="' + fs.toFixed(1) + '" text-anchor="middle"' + shadow + '>' + (typeof cur === 'number' ? fmtVal(cur) : '--') + '</text>';

  // ---- idle flag ----
  if (IDLE_TEXT && IDLE_BELOW > 0 && typeof cur === 'number' && cur < IDLE_BELOW)
    out += '<text x="' + lx.toFixed(2) + '" y="' + (pad + ifs * 0.9).toFixed(2) + '" fill="' + IDLE_COLOR + '" font-size="' + ifs.toFixed(1) + '" text-anchor="middle"' + shadow + '>' + IDLE_TEXT + '</text>';

  out += '</svg>';
  return out;
}
